import ActivityKit
import SwiftUI
import WidgetKit

struct ReadingSessionLiveActivity: Widget {
    var body: some WidgetConfiguration {
        ActivityConfiguration(for: ReadingSessionAttributes.self) { context in
            ReadingSessionStatusView(context: context)
                .padding()
        } dynamicIsland: { context in
            DynamicIsland {
                DynamicIslandExpandedRegion(.bottom) {
                    ReadingSessionStatusView(context: context)
                }
            } compactLeading: {
                Image(systemName: "book.fill")
            } compactTrailing: {
                if context.isFinished {
                    Image(systemName: "checkmark.circle.fill")
                } else {
                    Text(timerInterval: context.interval, countsDown: true)
                        .monospacedDigit()
                        .frame(width: 44)
                }
            } minimal: {
                Image(systemName: context.isFinished ? "checkmark.circle.fill" : "book.fill")
            }
        }
    }
}

private extension ActivityViewContext where Attributes == ReadingSessionAttributes {
    var isFinished: Bool { isStale || state.isFinished }
    var interval: ClosedRange<Date> { attributes.startDate...attributes.endDate }
}

private struct ReadingSessionStatusView: View {
    let context: ActivityViewContext<ReadingSessionAttributes>

    var body: some View {
        if context.isFinished {
            Label("Сессия окончена", systemImage: "checkmark.circle.fill")
                .font(.headline)
        } else {
            HStack {
                Label("Чтение", systemImage: "book.fill")
                    .font(.headline)
                Spacer()
                Text(timerInterval: context.interval, countsDown: true)
                    .font(.title2.monospacedDigit())
            }
        }
    }
}
```

## 6. Подключение в приложении

```swift
@main
struct SlumpyApp: App {
    @State private var readingSession = ReadingSessionManager()
    @Environment(\.scenePhase) private var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environment(readingSession)
        }
        .onChange(of: scenePhase) { _, phase in
            if phase == .active { readingSession.refresh() }
        }
    }
}
```

На экране со Slumpy:

```swift
@Environment(ReadingSessionManager.self) private var readingSession

// ...on the Slumpy view:
.onChange(of: readingSession.slumpyMessage, initial: true) { _, message in
    guard let message else { return }
    slumpy.say(message) // replace with the existing call that makes Slumpy speak
    readingSession.dismissSlumpyMessage()
}
```

Кнопка старта сессии: `try readingSession.start(blocking: selection)`. Здесь `selection` — это уже сохранённый у вас выбор приложений для блокировки.

## Допущения (решил сам)

1. **Старт сессии заменяется новым.** Старый код, который включал блокировку, нужно убрать и вызывать `start(...)`. Иначе блокировка останется включённой через старый механизм, и новый код её не снимет.
2. **Идентификатор App Group.** В `AppGroup.id` вставьте ваш идентификатор из настроек проекта.
3. **Дневная цель считается заново.** Минуты сохраняются по дням в общем файле, сегодняшние доступны как `readingSession.todayMinutes`. Если у вас уже есть свой счётчик цели, экран цели должен показывать это значение. Иначе засчитанные минуты там не появятся.
4. **Засчитывается вся длительность сессии.** Минуты идут в день старта, даже если сессия перешла через полночь.
5. **Сессия не короче 15 минут.** Это минимальный интервал, который iOS умеет отслеживать в фоне. 30 минут проходят без проблем.
6. **Только одна сессия одновременно.** Повторное нажатие «Старт» во время активной сессии ничего не делает.

## Ограничения
- **Live Activity может провисеть до открытия приложения.** Если приложение выгружено, карточка покажет «Сессия окончена», но с экрана блокировки исчезнет только при следующем открытии приложения или через системный лимит (до 8–12 часов). Надёжно убрать её без открытия приложения можно только пуш-уведомлением с сервера, а сервера у вас нет.
- **Есть факты об API, которые я не смог подтвердить.** Первый: что Live Activity сама перерисуется в «Сессия окончена» точно в момент окончания. Второй: что Swift 6 без ошибок примет передачу Live Activity в фоновую задачу. Оба проверятся первой сборкой и тестом на устройстве.

## Что исправлено после проверки
- **Испорченный общий файл.** Раньше при сбое чтения код перезаписывал файл пустыми данными. Терялись минуты, и блокировка могла остаться навсегда. Теперь файл в таком случае не трогается, а расширение всё равно снимает блокировку.
- **Пометка для Slumpy.** Она стиралась сразу при открытии и могла потеряться. Теперь стирается только после того, как Slumpy сказал фразу.
- **Блокировка сайтов по категориям.** Теперь выбранные категории блокируют и сайты в Safari, а не только приложения.
- **Ошибка сборки в Swift 6.** Убрал место, где она могла возникнуть.
- **Недосказанное в ответе.** Ограничение Live Activity и допущение про дневную цель теперь записаны выше.

## Что проверить на устройстве
1. Запустите сессию и свайпом закройте приложение. Через 30 минут заблокированные приложения должны открываться, а Live Activity — показывать «Сессия окончена».
2. Откройте приложение. Live Activity должна исчезнуть, Slumpy — сказать «Сессия окончена», а к сегодняшним минутам добавиться 30.
3. Откройте приложение ещё раз. Минуты не должны добавиться повторно, Slumpy не должен повторить фразу.

